1#include <iostream>
2#include <cstdlib>
3#include <ctime>
4using namespace std;
5
6class Game {
7    private:
8        string user_pick;
9        string computer_pick;
10        string result;
11
12    public:
13    
14        // function to return computer's pick
15        string get_computer_pick() {
16
17            // generate random number based on time
18            srand(time(NULL));
19
20            // random number between 1 and 3
21            int random_number = (rand() % 3) + 1;
22
23            switch(random_number) {
24                case 1:
25                    computer_pick = "rock";
26                    break;
27        
28                case 2:
29                    computer_pick = "paper";
30                    break;
31
32                case 3:
33                    computer_pick = "scissors";
34                    break;
35            }
36
37            return computer_pick;
38        }
39
40        // function to return user's pick
41        string get_user_pick() {
42
43            char user_input;
44
45            // get input until user enters 'r', 'p', or 's'
46            while (1) {
47
48                cout << "Enter Your Choice (r for rock, p for paper, s for scissors): ";
49                cin >> user_input;
50
51                // convert user_pick to lowercase
52                user_input = tolower(user_input);
53
54                // assign appropriate string to user_pick
55                if (user_input == 'r') {
56                    user_pick = "rock";
57
58                    // terminate while loop
59                    break;
60                }
61                else if (user_input == 'p') {
62                    user_pick = "paper";
63
64                    // terminate while loop
65                    break;
66                }
67                else if (user_input == 's') {
68                    user_pick = "scissors";
69
70                    // terminate while loop
71                    break;
72                }
73            }
74
75            return user_pick;
76        }
77
78        // return either "win", "lose" or "draw"
79        string get_result() {
80
81            // condition for user to draw
82            if (user_pick == computer_pick) {
83                result = "draw";
84            }
85
86            // condition for user to win
87            else if (user_pick == "paper" && computer_pick == "rock") {
88                result = "win";
89            }
90
91            else if (user_pick == "rock" && computer_pick == "scissors") {
92                result = "win";
93            }
94
95            else if (user_pick == "scissors" && computer_pick == "paper") {
96                result = "win";
97            }
98
99            // all other conditions result in loss
100            else {
101                result = "lose";
102            }
103            
104            return result;
105        }
106};
107
108int main() {
109
110    // create Game object
111    Game game;
112
113    // get user's pick
114    string user_pick = game.get_user_pick();
115
116    // get computer's pick
117    string computer_pick = game.get_computer_pick();
118
119    // check the result of the game
120    string result = game.get_result();
121
122    // print the result
123    cout << "User Pick: " << user_pick << endl;
124    cout << "Computer Pick: " << computer_pick << endl;
125    cout << "You " << result << endl;
126
127    return 0;
128}
